-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/gold/gold_live_encounter.sql, analytics/dbt/models/gold/gold_feed_freshness.sql. Do not edit.
-- Gold live encounter: the hospital admissions and emergency visits of the live Riverside General feed (demo,
-- invented patients on real dates), the base of the operational tables (census, bed board, weekly metrics, LACE).
-- The live feed is the HL7 v2 source with visit numbers that carry the date, V<yyyymmdd><nn> (hl7v2/generate.py).
-- The original 25 patient feed (visit numbers V70000 and up) is a static archive, like MIMIC and Synthea, and is
-- left out, as is everything from those two sources.
CREATE OR REPLACE TABLE gold_live_encounter AS
WITH live AS (
    SELECT s.*, e.identifier_value, e.priority_code
    FROM gold_encounter_summary s
    JOIN silver_encounter e ON e.encounter_id = s.encounter_id
    WHERE s.source = 'hl7v2'
      AND e.identifier_value LIKE 'V__________'
      AND s.encounter_kind IN ('hospital admission', 'emergency visit')
),
kidney AS (
    SELECT encounter_id, MIN(signal_at) AS first_kidney_signal_at
    FROM gold_aki_rise
    GROUP BY encounter_id
)
SELECT
    l.encounter_id,
    l.patient_id,
    l.identifier_value                                                        AS visit_number,
    l.encounter_kind,
    l.is_admission,
    l.priority_code,
    CASE WHEN l.is_admission AND l.priority_code = 'EM' THEN TRUE ELSE FALSE END AS is_emergency_admission,
    l.start_at,
    l.end_at,
    CAST(l.start_at AS DATE)                                                  AS start_date,
    CAST(l.end_at AS DATE)                                                    AS end_date,
    l.length_of_stay_days,
    l.next_admission_at,
    l.readmitted_30d,
    l.attending_practitioner_id,
    l.attending_name,
    l.last_location_id,
    l.last_location_name,
    l.last_unit_name,
    l.bed_moves,
    k.first_kidney_signal_at,
    CASE WHEN k.encounter_id IS NOT NULL THEN TRUE ELSE FALSE END             AS has_kidney_signal
FROM live l
LEFT JOIN kidney k ON k.encounter_id = l.encounter_id;

-- Gold feed freshness: one row saying how current the live feed data is. The nightly job loads yesterday, so the
-- data date (the "today" of the operational pages) is the day of the last feed event, never later than the extract.
-- All columns are NULL when the server has no live feed yet.
CREATE OR REPLACE TABLE gold_feed_freshness AS
WITH live AS (
    SELECT encounter_id, start_at, end_at FROM gold_live_encounter
),
events AS (
    SELECT start_at AS event_at FROM live
    UNION ALL
    SELECT end_at FROM live WHERE end_at IS NOT NULL
    UNION ALL
    SELECT o.effective_at FROM silver_observation o JOIN live ON live.encounter_id = o.encounter_id
),
extract_run AS (
    SELECT MAX(loaded_at) AS extracted_at FROM bronze_resources
),
last_event AS (
    SELECT MIN(event_at) AS first_event_at, MAX(event_at) AS last_event_at FROM events
)
SELECT
    CAST(e.first_event_at AS DATE)                                                 AS first_day,
    -- A manual run for today also writes events later in the day than the run itself: count nothing after the extract
    CASE WHEN e.last_event_at > x.extracted_at THEN x.extracted_at ELSE e.last_event_at END   AS last_event_at,
    CASE WHEN e.last_event_at IS NULL THEN NULL
         WHEN e.last_event_at > x.extracted_at THEN CAST(x.extracted_at AS DATE)
         ELSE CAST(e.last_event_at AS DATE) END                                    AS data_date,
    x.extracted_at,
    CAST(x.extracted_at AS DATE)                                                   AS extract_date
FROM last_event e
CROSS JOIN extract_run x;
